mapper.select:
SELECT RESULT_TB.PREVDATE_COUNT , (RESULT_TB.MB_COUNT - RESULT_TB.WD_COUNT) AS CUMUL_COUNT , RESULT_TB.PREVDATE_TOTALPAY , RESULT_TB.CUMUL_TOTALPAY , RESULT_TB.PREV_ORIGINAL_AMOUNT , RESULT_TB.CUMUL_ORIGINAL_AMOUNT , RESULT_TB.REPAYMENT_REMAINING_AMOUNT , RESULT_TB.PREVDATE_REPAY_COUNT , RESULT_TB.CUMUL_REPAY_COUNT FROM(
SELECT SUM(IFNULL((SELECT COUNT(MUIS.SEQ) FROM MONEYBANK_USER_INFO MUIS WHERE DATE_FORMAT(MUIS.MONEYBANK_REQUEST_DATE, '%Y-%m-%d') = #{toDate} AND MUI.SEQ = MUIS.SEQ), 0)) AS PREVDATE_COUNT, SUM(IFNULL((SELECT COUNT(MUIS.SEQ) FROM MONEYBANK_USER_INFO MUIS WHERE MUI.SEQ = MUIS.SEQ AND DATE_FORMAT(MUIS.MONEYBANK_REQUEST_DATE, '%Y-%m-%d') <= #{toDate}), 0)) AS MB_COUNT, SUM(IFNULL((SELECT COUNT(MUIS.SEQ) FROM MONEYBANK_USER_INFO MUIS LEFT JOIN CBCI_USER CUS ON MUIS.USER_NO = CUS.USER_NO WHERE MUI.SEQ = MUIS.SEQ AND DATE_FORMAT(CUS.WITHDRAW_DATE, '%Y-%m-%d') <= #{toDate}), 0)) AS WD_COUNT, ROUND(SUM(IFNULL((SELECT SUM(TRIS.total_payment) FROM HELLOPAY_B2B_EXECUTE_INFO TRIS LEFT JOIN MONEYBANK_USER_INFO MUIS ON MUIS.SEQ = TRIS.SEQ WHERE TRIS.FINAL_REPAYMENT_YN='N' AND DATE_FORMAT(MUIS.MONEYBANK_REQUEST_DATE, '%Y-%m-%d') = #{toDate}), 0))/1000000, 1) AS PREVDATE_TOTALPAY, ROUND(IFNULL((SELECT SUM(TRIS.total_payment) FROM HELLOPAY_B2B_EXECUTE_INFO TRIS LEFT JOIN MONEYBANK_USER_INFO MUIS ON MUIS.SEQ = TRIS.SEQ WHERE DATE_FORMAT(MUIS.MONEYBANK_REQUEST_DATE, '%Y-%m-%d') <= #{toDate}), 0)/1000000, 1) AS CUMUL_TOTALPAY, ROUND(IFNULL((SELECT SUM(SUB_RESULT.original_amount) FROM((SELECT TRS.original_amount FROM HELLOPAY_B2B_REPAYMENT TRS WHERE DATE_FORMAT(TRS.repayment_date, '%Y-%m-%d') = #{toDate}) SUB_RESULT)), 0)/1000000, 1) AS PREV_ORIGINAL_AMOUNT, ROUND(IFNULL((SELECT SUB_RESULT.ORIGINAL_AMOUNT FROM((SELECT SUM(TRS.original_amount) AS ORIGINAL_AMOUNT FROM HELLOPAY_B2B_REPAYMENT TRS WHERE DATE_FORMAT(TRS.REPAYMENT_DATE, '%Y-%m-%d') <= #{toDate}) AS SUB_RESULT)), 0)/1000000, 1) AS CUMUL_ORIGINAL_AMOUNT, ROUND(IFNULL((SELECT SUM(SUB_RESULT.REPAYMENT_REMAINING_AMOUNT) AS REPAYMENT_REMAINING_AMOUNT FROM( SELECT DISTINCT RP.SEQ, (SELECT MIN(TRS.repayment_remaining_amount) FROM HELLOPAY_B2B_REPAYMENT TRS WHERE RP.seq = TRS.seq) AS REPAYMENT_REMAINING_AMOUNT FROM HELLOPAY_B2B_REPAYMENT RP ) SUB_RESULT ), 0)/1000000, 1) AS REPAYMENT_REMAINING_AMOUNT, (SELECT COUNT(DISTINCT TRS.seq) FROM HELLOPAY_B2B_REPAYMENT TRS LEFT JOIN HELLOPAY_B2B_EXECUTE_INFO TRIS ON TRS.seq=TRIS.seq WHERE TRS.repayment_date = #{toDate}) AS PREVDATE_REPAY_COUNT, (SELECT COUNT(DISTINCT TRS.seq) FROM HELLOPAY_B2B_REPAYMENT TRS LEFT JOIN HELLOPAY_B2B_EXECUTE_INFO TRIS ON TRS.seq=TRIS.seq WHERE TRS.repayment_date <= #{toDate}) AS CUMUL_REPAY_COUNT FROM MONEYBANK_USER_INFO MUI
)RESULT_TB

SELECT
FOUND_ROWS() AS TOTAL_COUNT, RESULT_TB.*
COUNT(*) AS TOTAL_SEQ ,SUM(RESULT_TB.B2B_LIMIT_AMOUNT) AS TOTAL_AMOUNTS ,SUM(RESULT_TB.ORIGINAL_AMOUNT) AS TOTAL_ORIGINAL_AMOUNT ,SUM(RESULT_TB.REMAINING_AMOUNT) AS TOTAL_REMAINING_AMOUNT
FROM( SELECT @det_row_no := @det_row_no + 1 AS RNUM, MUI.SEQ, MUI.REQUEST_STATUS, CU.USER_NO, IFNULL(DATE_FORMAT(MUI.CONTRACT_DATE, '%Y-%m-%d'), "-") AS CONTRACT_DATE, CU.USER_NM, CU.FIRM_NM , CU.USER_ID , MUI.DIVISION , CU.USER_PHONE , IFNULL(CU.FIRM_TEL, "-") AS FIRM_TEL , MUI.B2B_LIMIT_AMOUNT , IFNULL((SELECT HRI_INNER.daily_usage_fee FROM HELLOPAY_B2B_EXECUTE_INFO HRI_INNER WHERE HRI_INNER.seq = MUI.SEQ LIMIT 1), 0) AS DAILY_USAGE_FEE , IFNULL((SELECT HRI_INNER.daily_interest_fee FROM HELLOPAY_B2B_EXECUTE_INFO HRI_INNER WHERE HRI_INNER.seq = MUI.SEQ LIMIT 1), 0) AS DAILY_INTEREST_RATE , IFNULL((SELECT CPR.BUSINESS_PERIOD FROM CBCI_PRIZM_RESULT CPR WHERE CPR.SEQ = MUI.SEQ ORDER BY CPR.INPUT_DATE DESC LIMIT 1), 'TBD') AS BUSINESS_PERIOD , IFNULL((SELECT CPR.MONTH_SALES_VALUE FROM CBCI_PRIZM_RESULT CPR WHERE CPR.SEQ = MUI.SEQ ORDER BY CPR.INPUT_DATE DESC LIMIT 1), 'TBD') AS MONTH_SALES_VALUE , IFNULL((SELECT CPR.PRIZM_SCORE FROM CBCI_PRIZM_RESULT CPR WHERE CPR.SEQ = MUI.SEQ ORDER BY CPR.INPUT_DATE DESC LIMIT 1), 'TBD') AS PRIZM_SCORE , IFNULL((SELECT SUM(HBR.original_amount) FROM HELLOPAY_B2B_REPAYMENT HBR LEFT JOIN HELLOPAY_B2B_EXECUTE_INFO HBI ON HBR.seq = HBI.seq WHERE MUI.SEQ = HBR.seq AND HBI.final_repayment_yn='N'), 0) AS ORIGINAL_AMOUNT , IFNULL((SELECT MIN(HBR.repayment_remaining_amount) FROM (SELECT seq, repayment_remaining_amount FROM HELLOPAY_B2B_REPAYMENT WHERE repayment_remaining_amount != 0) HBR LEFT JOIN HELLOPAY_B2B_EXECUTE_INFO HBI ON HBR.seq = HBI.seq WHERE MUI.SEQ = HBR.seq AND HBI.final_repayment_yn = 'N'), 0) AS REMAINING_AMOUNT FROM MONEYBANK_USER_INFO MUI LEFT JOIN CBCI_USER CU ON MUI.USER_NO = CU.USER_NO , (SELECT @det_row_no := 0) DET_ROW_NO WHERE CU.USER_ID LIKE #{USER_ID} AND CU.USER_NM LIKE #{REP_NM} -- 회원명 대표자명으로 검색 AND CU.FIRM_NM LIKE #{FIRM_NM} -- 회사명으로 검색
AND MUI.CONTRACT_DATE >= #{fromDate}
AND MUI.CONTRACT_DATE <= #{toDate}
AND MUI.B2B_LIMIT_AMOUNT BETWEEN ${minAmount} AND ${maxAmount}
AND MUI.DIVISION = #{DIVISION}
ORDER BY ${ORDER_BY} )RESULT_TB
LIMIT ${LIMIT}
